package br.com.onda;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class RadioCityTest {
 private RadioCity city(){return new RadioCity("Campo Grande","Mato Grosso do Sul","BR","Brasil",-20.4697,-54.6201);}
 @Test public void distanceSeparatesNearbyAndUnrelatedCities(){RadioCity c=city();assertEquals(0,c.distance(c.latitude,c.longitude),.001);assertTrue(c.distance(-20.48,-54.61)<5);assertTrue(c.distance(-23.5505,-46.6333)>800);assertEquals(Double.POSITIVE_INFINITY,c.distance(Double.NaN,0),0);assertEquals(Double.POSITIVE_INFINITY,c.distance(91,0),0);}
 @Test public void invalidCoordinatesAndEmptyNamesAreRejected(){for(double[] xy:new double[][]{{91,0},{0,181},{Double.NaN,0},{0,Double.POSITIVE_INFINITY}})try{new RadioCity("Cidade","","BR","Brasil",xy[0],xy[1]);fail();}catch(IllegalArgumentException expected){}assertNull(RadioCity.decode("{}"));assertEquals(city().key(),RadioCity.decode(cityJson()).key());}
 private String cityJson(){try{return city().json().toString();}catch(Exception e){throw new RuntimeException(e);}}
 @Test public void cityNamesAreDisambiguatedByStateAndCachePreservesChoice()throws Exception{String raw=new JSONArray().put(new JSONArray().put("Campo Grande").put("Mato Grosso do Sul").put("MS").put(-20.4697).put(-54.6201).put(1)).put(new JSONArray().put("Campo Grande").put("Alagoas").put("AL").put(-9.95).put(-36.79).put(0)).toString();List<RadioCity> both=RadioCity.local(raw,"Campo Grande");assertEquals(2,both.size());List<RadioCity> chosen=RadioCity.local(raw,"Campo Grande AL");assertEquals(1,chosen.size());assertEquals("Alagoas",chosen.get(0).state);assertEquals(chosen.get(0).key(),RadioCity.read(RadioCity.write(chosen)).get(0).key());}
 @Test public void lookupUrlsEncodeThemeAndRespectCountry()throws Exception{String old=RadioDirectory.path("Rádio & Música",true,null,0);assertTrue(old.contains("limit=100"));assertTrue(old.contains("countrycode=BR"));assertFalse(old.contains("has_geo_info"));String city=RadioDirectory.path("",false,city(),500);assertTrue(city.contains("has_geo_info=true"));assertTrue(city.contains("countrycode=BR"));assertTrue(city.contains("offset=500"));assertTrue(city.contains("is_https=true"));}
 private JSONObject station(String id,double lat,double lon,String country,String url)throws Exception{return new JSONObject().put("stationuuid",id).put("name",id).put("url_resolved",url).put("countrycode",country).put("country","Brasil").put("geo_lat",lat).put("geo_long",lon);}
 @Test public void cityResultsExcludeMissingCoordinatesOtherCountriesAndUnsafeStreams()throws Exception{RadioCity c=city();JSONArray rows=new JSONArray().put(station("near",c.latitude,c.longitude,"BR","https://radio.example.org/live")).put(station("other-city",-23.5505,-46.6333,"BR","https://radio.example.org/sp")).put(station("wrong-country",c.latitude,c.longitude,"PY","https://radio.example.org/py")).put(station("unsafe",c.latitude,c.longitude,"BR","http://radio.example.org/no"));JSONObject missing=station("no-geo",0,0,"BR","https://radio.example.org/missing");missing.remove("geo_lat");rows.put(missing);List<RadioStation> result=RadioDirectory.located(rows.toString(),c);assertEquals(1,result.size());assertEquals("near",result.get(0).id);String saved=RadioStation.write(result);assertEquals("near",RadioStation.read(saved,false).get(0).id);}
 @Test public void bundledBrazilCitiesMatchAccentsAndStateWithoutNetwork()throws Exception{String configured=System.getProperty("onda.cities.asset","");java.nio.file.Path asset=null;for(String file:new String[]{configured,"src/main/assets/radio-cities-br.json","app/src/main/assets/radio-cities-br.json","Onda/app/src/main/assets/radio-cities-br.json"})if(!file.isEmpty()&&java.nio.file.Files.isRegularFile(java.nio.file.Path.of(file))){asset=java.nio.file.Path.of(file);break;}assertNotNull("Bundled cities asset missing",asset);String raw=java.nio.file.Files.readString(asset);assertTrue(new JSONArray(raw).length()>=5500);List<RadioCity> ms=RadioCity.local(raw,"Campo Grande MS");assertEquals(1,ms.size());assertEquals("Mato Grosso do Sul",ms.get(0).state);assertEquals("São Paulo",RadioCity.local(raw,"sao paulo").get(0).name);assertEquals("Paraíba",RadioCity.local(raw,"Campina Grande PB").get(0).state);assertTrue(RadioCity.local(raw,"Cidade inexistente zzz").isEmpty());}

}
